def st(t,icon,name,se,stt,done,**kw):
  d={"type":t,"icon":icon,"name":name,"sticker":{"e":se,"t":stt},"done":done};d.update(kw);return d
def it(e,n,to,why,hint): return {"e":e,"n":n,"to":to,"why":why,"hint":hint}
def o(*p): return [{"e":p[i],"n":p[i+1]} for i in range(0,len(p),2)]
def tf(e,t,a,why,hint): return {"e":e,"t":t,"a":a,"why":why,"hint":hint}
def S(e,t): return {"e":e,"t":t}
def pr(a,an,b,bn,why): return {"a":a,"an":an,"b":b,"bn":bn,"why":why}
